import {chromium} from '@playwright/test';
import fs from 'node:fs/promises';
import {KEY,scenarioState} from '../src/model.js';
const dir='检查记录/全站查缺补漏_20261022';await fs.mkdir(dir+'/审查截图',{recursive:true});
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});
const p=await browser.newPage({viewport:{width:1440,height:1000}});p.setDefaultTimeout(5000);p.setDefaultNavigationTimeout(25000);const errors=[],rows=[];let route='';p.on('pageerror',e=>errors.push({route,error:e.message}));
await p.goto('http://127.0.0.1:5184/plan',{waitUntil:'domcontentloaded'});
const groups=[['入门','/onboarding',[''],['PT01']],['工作区','/app',[''],['PT01','PT05']],['评估','/assessment',['','原文确认','四维与差距','成果档案','当前简历'],['PT01','PT05']],['探索','/careers',['','比较','企业与岗位','我的机会'],['PT01','PT05']],['地图','/career-map',['技能先修','职业关系'],['PT01']],['计划','/plan',['','执行','复盘'],['PT01','PT05']],['日程','/plan?view=calendar',['执行'],['PT01','PT05']],['学习','/learning',['','短体验','综合项目'],['PT01','PT05']],['学习收藏','/learning?collection=收藏',[''],['PT01']],['我的学习','/learning?collection=我的学习',[''],['PT05']],['任务','/work/task-demo',['','笔记与阅读','尝试与反馈','贡献与表达','完成回执'],['PT06']],['外部实践','/plan?tab=执行&practice=task-demo',[''],['S1']],['报告','/reports',['','岗位简历'],['PT01','PT05']],['旧报告','/reports/report-demo',[''],['PT07']],['AI','/assistant',['','自然语言检索'],['PT01','PT05']],['设置','/settings',['','资料与隐私'],['PT01','PT05']],['运营','/admin/quality',['','质量与服务','权限审计'],['quality']],['来源','/admin/data',['','语义与条件','发布与撤回'],['data']],['内容','/admin/content',['','关系先修','学习项目','发布历史'],['content']],['权限拒绝','/admin/data',[''],['PT01']],['失效任务','/work/missing',[''],['PT05']],['失效报告','/reports/missing',[''],['PT05']],['未知页','/missing',[''],['PT01']]];
try{for(const [name,path,tabs,scenes]of groups)for(const scene of scenes)for(const tab of tabs){const u=new URL(path,'http://127.0.0.1:5184');if(tab)u.searchParams.set('tab',tab);route=u.pathname+u.search;const s=scenarioState(scene.startsWith('PT')?scene:'PT05');if(['quality','data','content'].includes(scene))s.role=scene;if(scene==='S1')s.stage='S1';await p.evaluate(({s,k})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language','zh');localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s,k:KEY});try{await p.goto(u.href,{waitUntil:'domcontentloaded'});await p.locator('.page-surface').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});const data=await p.locator('.page-surface').evaluate(el=>({title:el.querySelector('h1')?.textContent,headings:[...el.querySelectorAll('h2,h3')].map(e=>e.textContent),text:el.innerText.slice(0,1500),controls:el.querySelectorAll('input,textarea,select,button,a').length,unlabelled:[...el.querySelectorAll('input:not([type=hidden]),textarea,select')].filter(e=>!e.labels?.length&&!e.getAttribute('aria-label')&&!e.getAttribute('aria-labelledby')&&!e.getAttribute('title')).map(e=>({tag:e.tagName,name:e.name,placeholder:e.placeholder})),links:[...el.querySelectorAll('a[href]')].map(e=>({text:e.innerText,href:e.getAttribute('href')})),width:el.clientWidth,scroll:el.scrollWidth}));const row={name,route,scene,status:'read',...data};if(process.argv[2]!=='复核'&&(scene==='PT01'||scene==='PT06'||['quality','data','content'].includes(scene))&&name!=='地图'){const filename=(rows.length+1)+'-'+name+'-'+(tab||'默认')+'-'+scene+'.png';await p.locator('.page-surface').evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/审查截图/'+filename});row.screenshot=filename;}rows.push(row);}catch(e){rows.push({name,route,scene,status:'failed',error:e.message});} }
}finally{await fs.writeFile(dir+'/'+(process.argv[2]||'初始')+'路由审查.json',JSON.stringify({rows,errors},null,2));await browser.close();}
console.log(JSON.stringify({routes:rows.length,failed:rows.filter(r=>r.status==='failed'),errors,unlabelled:rows.filter(r=>r.unlabelled?.length).map(r=>({route:r.route,items:r.unlabelled})),overflow:rows.filter(r=>r.scroll>r.width+1).map(r=>r.route)}));
